117	// runTrailShow shows one trail, defaulting to the current branch's trail.
118	func runTrailShow(ctx context.Context, w, errW io.Writer, insecureHTTP bool, selector string) error {
119		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, func(ctx context.Context, client *api.Client) error {
120			forge, owner, repo, err := resolveTrailRemote(ctx)
121			if err != nil {
122				return err
123			}
124	
125			found, err := resolveTrailBySelector(ctx, client, forge, owner, repo, selector)
126			if err != nil {
127				return err
128			}
129	
130			// Enrich the list result with the detail endpoint, which carries the
131			// rendered description (trail.body_document.text_snapshot) the list
132			// omits, and surface a browser URL. The detail fetch is best-effort:
133			// the core metadata already came from the list, so a detail failure
134			// falls back to the list body with a warning rather than failing.
135			m := found.ToMetadata()
136			webURL := ""
137			// Seed the description from the list body so a failed (or skipped)
138			// detail fetch still shows something; a successful detail fetch
139			// supersedes it with the richer body_document text below.
140			bodyText := found.Body
141			descriptionLoaded := strings.TrimSpace(found.Body) != ""
142			if found.Number > 0 {
143				webURL = trailWebURL(api.BaseURL(), forge, owner, repo, found.Number)
144				if bt, derr := fetchTrailDescription(ctx, client, forge, owner, repo, found.Number); derr == nil {
145					// A successful fetch means we authoritatively consulted the
146					// description, but it only supersedes the seeded list body when
147					// it actually carries text: an older/partial server that omits
148					// body_document returns "" here and must not blank out a list
149					// body that is present.
150					descriptionLoaded = true
151					if strings.TrimSpace(bt) != "" {
152						bodyText = bt
153					}
154				} else {
155					// Best-effort: warn but still render metadata + URL (and the
156					// list body) rather than failing the whole command.
157					fmt.Fprintf(errW, "Warning: could not load trail description: %v\n", derr)
158				}
159			}
160			printTrailDetails(w, m, webURL, trailDescriptionForDisplay(bodyText, descriptionLoaded))
161			return nil
162		})
163	}
