226	// noTrailDescription is shown by `trail show` when a trail's description loaded
227	// successfully but is empty — distinguishing "no description yet" from a load
228	// failure (which warns and renders nothing).
229	const noTrailDescription = "-- no description provided --"
230	
231	// trailDescriptionForDisplay returns the text `trail show` renders for the
232	// description: the body when present; the placeholder when it loaded but is
233	// empty; or "" when it couldn't be loaded (the caller has already warned).
234	func trailDescriptionForDisplay(bodyText string, loaded bool) string {
235		if strings.TrimSpace(bodyText) != "" {
236			return bodyText
237		}
238		if loaded {
239			return noTrailDescription
240		}
241		return ""
242	}
