253	// fetchTrailDescription fetches a trail's rendered description text
254	// (`trail.body_document.text_snapshot`), which the list endpoint omits, by
255	// integer number. It returns only the description — the list result already
256	// supplies the metadata — and decodes only the fields it needs, so it is
257	// unaffected by the shape of sibling fields like `checkpoints`/`thread`.
258	func fetchTrailDescription(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (string, error) {
259		resp, err := client.Get(ctx, trailNumberPath(forge, owner, repo, number))
260		if err != nil {
261			return "", fmt.Errorf("failed to fetch trail detail: %w", err)
262		}
263		defer resp.Body.Close()
264		if err := checkTrailResponse(resp); err != nil {
265			return "", err
266		}
267		var detail struct {
268			Trail api.TrailResource `json:"trail"`
269		}
270		if err := api.DecodeJSON(resp, &detail); err != nil {
271			return "", fmt.Errorf("failed to decode trail detail: %w", err)
272		}
273		if detail.Trail.BodyDocument == nil {
274			return "", nil
275		}
276		return strings.TrimSpace(detail.Trail.BodyDocument.TextSnapshot), nil
277	}
