666	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
667		ctx := cmd.Context()
668		w := cmd.OutOrStdout()
669		errW := cmd.ErrOrStderr()
670	
671		repo, err := strategy.OpenRepository(ctx)
672		if err != nil {
673			return fmt.Errorf("failed to open repository: %w", err)
674		}
675		defer repo.Close()
676	
677		// Determine base branch.
678		if base == "" {
679			base = strategy.GetDefaultBranchName(repo)
680			if base == "" {
681				base = defaultBaseBranch
682			}
683		}
684	
685		_, currentBranch, _ := isOnDefaultBranchRepo(repo) //nolint:errcheck // best-effort; reuse the open repo for the current branch name
686		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
687	
688		if interactive {
689			// Interactive flow: title → body → branch (derived) → status.
690			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
691				return handleFormCancellation(w, "Trail creation", err)
692			}
693		} else {
694			// Non-interactive: derive missing values from provided flags. With
695			// --branch omitted, use the checked-out branch (a feature branch); only
696			// slug a new branch from the title when the checked-out branch is the base.
697			branch = resolveCreateBranch(branch, currentBranch, base, title, cmd.Flags().Changed("title"))
698			if title == "" {
699				title = trail.HumanizeBranchName(branch)
700			}
701		}
702		title = strings.TrimSpace(title)
703		base = strings.TrimSpace(base)
704		branch = strings.TrimSpace(branch)
705		statusStr = strings.TrimSpace(statusStr)
706		if title == "" {
707			return errors.New("trail title is required")
708		}
709		if branch == "" {
710			return errors.New("branch name is required")
711		}
712		if err := ValidateBranchName(ctx, branch); err != nil {
713			return err
714		}
715		if statusStr == "" {
716			statusStr = string(trail.StatusOpen)
717		}
718		if status := trail.Status(statusStr); !status.IsValid() {
719			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
720		}
721	
722		needsCreation := branchNeedsCreation(repo, branch)
723	
724		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
725		if err != nil {
726			return renderDataAPIAuthError(cmd.ErrOrStderr(), err)
727		}
728		forge, owner, repoName, err := resolveTrailRemote(ctx)
729		if err != nil {
730			return err
731		}
732	
733		localBranchCreated := false
734		var remoteBranchPushed bool
735	
736		// Don't delete a remote branch we didn't create during cleanup.
737		existedOnOrigin, existErr := branchExistsOnOrigin(branch)
738		if existErr != nil {
739			fmt.Fprintf(errW, "Warning: could not check whether branch %s already exists on origin: %v\n", branch, existErr)
740			existedOnOrigin = true
741		}
742	
743		if needsCreation {
744			if existedOnOrigin {
745				if err := fetchBranchFromOrigin(branch); err != nil {
746					return fmt.Errorf("failed to fetch branch %q from origin: %w", branch, err)
747				}
748				localBranchCreated = true
749				fmt.Fprintf(w, "Fetched branch %s from origin\n", branch)
750			} else {
751				if err := createBranch(repo, branch); err != nil {
752					return fmt.Errorf("failed to create branch %q: %w", branch, err)
753				}
754				localBranchCreated = true
755				fmt.Fprintf(w, "Created branch %s\n", branch)
756			}
757		} else if currentBranch != branch {
758			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
759		}
760	
761		// Always push the branch first: the trail binds to a remote branch, so
762		// deliver it before creating the trail rather than letting the server
763		// backfill it at the base tip.
764		{
765			if err := pushBranchToOrigin(branch); err != nil {
766				cleanupCreatedTrailBranch(repo, branch, localBranchCreated, false, errW)
767				return fmt.Errorf("failed to push branch %q to origin: %w\nhint: the trail was not created because its branch could not be delivered to the remote.\n  - if this is an auth error, link your GitHub account and retry\n  - if this is a non-fast-forward, update branch %q from origin and retry", branch, err, branch)
768			}
769			remoteBranchPushed = !existedOnOrigin
770			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
771		}
772	
773		createReq := newTrailCreateRequest(title, body, branch, base, statusStr)
774	
775		var createResp api.TrailCreateResponse
776		resp, err := client.Post(ctx, trailsBasePath(forge, owner, repoName), createReq)
777		if err != nil {
778			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
779			return fmt.Errorf("failed to create trail: %w", err)
780		}
781		defer resp.Body.Close()
782		if err := checkTrailResponse(resp); err != nil {
783			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
784			return err
785		}
786	
787		if err := api.DecodeJSON(resp, &createResp); err != nil {
788			cleanupCreatedTrailBranch(repo, branch, localBranchCreated, remoteBranchPushed, errW)
789			return fmt.Errorf("failed to decode create response: %w", err)
790		}
791	
792		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.ID)
793	
794		if needsCreation && currentBranch != branch {
795			shouldCheckout := checkout
796			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
797				// Interactive: ask whether to checkout
798				form := NewAccessibleForm(
799					huh.NewGroup(
800						huh.NewConfirm().
801							Title(fmt.Sprintf("Check out branch %s?", branch)).
802							Value(&shouldCheckout),
803					),
804				)
805				if formErr := form.Run(); formErr == nil && shouldCheckout {
806					checkout = true
807				}
808			}
809			if checkout {
810				if err := CheckoutBranch(ctx, branch); err != nil {
811					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
812				}
813				fmt.Fprintf(w, "Switched to branch %s\n", branch)
814			}
815		}
816	
817		return nil
818	}
